# ProtosEQ CRM - Day 2.5 theme update (Madden HUD)
# Run from project root

$ErrorActionPreference = 'Stop'

if (-not (Test-Path 'package.json')) {
    Write-Host 'ERROR: run this from your project root.' -ForegroundColor Red
    exit 1
}

$files = @{}
$files['app/globals.css'] = ''
$files['app/layout.tsx'] = ''
$files['app/(auth)/layout.tsx'] = ''
$files['app/(auth)/login/page.tsx'] = ''
$files['components/app/sidebar.tsx'] = ''
$files['components/app/header.tsx'] = ''
$files['app/(app)/dashboard/page.tsx'] = ''

Write-Host ''
Write-Host '-> Updating theme files' -ForegroundColor Cyan

foreach ($path in $files.Keys) {
    $content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($files[$path]))
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $fullPath = Join-Path -Path (Get-Location) -ChildPath $path
    [System.IO.File]::WriteAllText($fullPath, $content, [System.Text.UTF8Encoding]::new($false))
    Write-Host ('  + ' + $path) -ForegroundColor Green
}

Write-Host ''
Write-Host '====================================' -ForegroundColor Green
Write-Host '  Theme update complete' -ForegroundColor Green
Write-Host '====================================' -ForegroundColor Green
Write-Host ''
Write-Host 'Dev server should hot-reload automatically.' -ForegroundColor Cyan
Write-Host 'If not, refresh your browser at http://localhost:3000'
Write-Host ''